#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using ld = long double;

ll x[25], y[25], a[25], n, l, r;
ld limit;
const ld pi = acosl(-1.0L);
const ld eps = 1e-61L;

ld func(ld dist, ll id) {
    ld ax = x[id] - (l + dist);
    ld ay = y[id];
    ld len = sqrtl(ax * ax + ay * ay);
    ld angle = acosl(ax / len);
    ld given = a[id] / 180.0L * pi;
    ld third = pi - angle - given;

    if (third < eps)
        return limit;

    ld distance = sinl(given) * len / sinl(third);
    return min(dist + distance, limit);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> l >> r;
    limit = r - l;

    for (ll i = 0; i < n; ++i)
        cin >> x[i] >> y[i] >> a[i];

    const size_t totalMasks = size_t{1} << n;
    vector<ld> dp(totalMasks, 0.0L);

    for (size_t mask = 1; mask < totalMasks; ++mask) {
        for (ll i = 0; i < n; ++i) {
            if (mask & (size_t{1} << i)) {
                dp[mask] = max(
                    dp[mask],
                    func(dp[mask ^ (size_t{1} << i)], i)
                );
            }
        }
    }

    cout << fixed << setprecision(10) << dp[totalMasks - 1];
    return 0;
}

